import '@testing-library/jest-dom'

import { act, render, screen } from '@testing-library/react'
import { LogicWrapper, MakeLogicType, actions, getContext, kea, path, reducers, useValues } from 'kea'

import { initKeaTests } from '~/test/init'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface counterTestLogicValues {
    count: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface counterTestLogicActions {
    increment: () => {
        value: true
    }
}

export type counterTestLogicType = MakeLogicType<counterTestLogicValues, counterTestLogicActions>

const counterTestLogic = kea<counterTestLogicType>([
    path(['lib', 'keaMidDispatchSnapshot', 'counterTestLogic']),
    actions({ increment: true }),
    reducers({ count: [0, { increment: (state) => state + 1 }] }),
])

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reentrantTestLogicValues {
    step: number
    total: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reentrantTestLogicActions {
    bump: () => {
        value: true
    }
}

export type reentrantTestLogicType = MakeLogicType<reentrantTestLogicValues, reentrantTestLogicActions>

// A reducer that reads a kea value re-enters the store while redux is still running the
// reducer, which is the condition redux's getState guard refuses.
const reentrantTestLogic: LogicWrapper<reentrantTestLogicType> = kea<reentrantTestLogicType>([
    path(['lib', 'keaMidDispatchSnapshot', 'reentrantTestLogic']),
    actions({ bump: true }),
    reducers({
        step: [2, {}],
        total: [0, { bump: (state: number) => state + reentrantTestLogic.values.step }],
    }),
])

function Count(): JSX.Element {
    const { count } = useValues(counterTestLogic)
    return <span>count is {count}</span>
}

// Guards patches/kea@4.0.0-pre.6.patch: kea reads store state both on the render path and on
// the dispatch path, and either read can land while a redux dispatch is still running (seen on
// Firefox), where getState() throws. The patch must fall back to the last good snapshot.
describe('kea mid-dispatch store read guard', () => {
    beforeEach(() => {
        initKeaTests()
    })

    it('survives getState throwing mid-dispatch and recovers on the next read', () => {
        render(<Count />)
        expect(screen.getByText('count is 0')).toBeInTheDocument()

        const store = getContext().store
        const realGetState = store.getState
        let calls = 0
        store.getState = () => {
            calls += 1
            throw new Error('You may not call store.getState() while the reducer is executing.')
        }

        try {
            expect(() => {
                act(() => {
                    counterTestLogic.actions.increment()
                })
            }).not.toThrow()
        } finally {
            store.getState = realGetState
        }
        expect(calls).toBeGreaterThan(0)

        act(() => {
            counterTestLogic.actions.increment()
        })
        expect(screen.getByText('count is 2')).toBeInTheDocument()
    })

    it('lets a reducer read a value during its own dispatch', () => {
        reentrantTestLogic.mount()

        expect(() => reentrantTestLogic.actions.bump()).not.toThrow()
        expect(reentrantTestLogic.values.total).toEqual(2)
    })
})
